export default function Review({ id }: { id: number }) {
  const [biz, setBiz] = useState<Business | null>(null);
  const [profile, setProfile] = useState<Profile | null>(null);
  const [subdomain, setSubdomain] = useState("");
  const [ownerEmail, setOwnerEmail] = useState("");
  const [orders, setOrders] = useState<Order[]>([]);
  const [loadError, setLoadError] = useState<ApiError | null>(null);
  const [saveError, setSaveError] = useState<ApiError | null>(null);
  const [saving, setSaving] = useState(false);
  const [savedAt, setSavedAt] = useState<Date | null>(null);
  const [dirty, setDirty] = useState(false);

  useEffect(() => {
    api
      .get(id)
      .then((b) => {
        setBiz(b);
        setProfile(b.profile);
        setSubdomain(b.subdomain);
        setOwnerEmail(b.owner_email);
        const k = keys.owner(id);
        if (k) keys.setOwner(id, k, b.profile.name);
      })
      .catch(setLoadError);
    api.orders(id).then(setOrders).catch(() => setOrders([]));
  }, [id]);

  if (loadError) return <ErrorBox error={loadError} />;
  if (!profile || !biz) return <p>Loading…</p>;

  const update = (patch: Partial<Profile>) => {
    setProfile({ ...profile, ...patch });
    setDirty(true);
  };
  const updateProduct = (i: number, patch: Partial<Product>) =>
    update({ products: profile.products.map((p, j) => (j === i ? { ...p, ...patch } : p)) });

  async function save(e: FormEvent) {
    e.preventDefault();
    if (!profile) return;
    setSaving(true);
    setSaveError(null);
    try {
      const cleaned = { ...profile, products: profile.products.filter((p) => p.name.trim()) };
      const b = await api.save(id, cleaned, subdomain, ownerEmail.trim());
      setBiz(b);
      setProfile(b.profile);
      setSubdomain(b.subdomain);
      setOwnerEmail(b.owner_email);
      setSavedAt(new Date());
      setDirty(false);
    } catch (err) {
      setSaveError(err instanceof ApiError ? err : new ApiError(String(err), 0));
    } finally {
      setSaving(false);
    }
  }

  const host = biz.site_url ? new URL(biz.site_url).host.replace(/^[^.]+/, "") : "";

                setDirty(true);
              }}
              maxLength={42}
            />
            <span className="muted">{host}</span>
          </div>
          <small>A free address to start with. You can get your own name later.</small>
        </label>
      </section>

      <h2>Your personal email</h2>
      <section className="card">
        <label className="field">
          <span>Email for warnings</span>
          <input
            type="email"
            value={ownerEmail}
            onChange={(e) => {
              setOwnerEmail(e.target.value);
              setDirty(true);
            }}
            placeholder="[redacted-email]"
            maxLength={254}
          />
          <small>
            Only for warnings about your website, for example if it stops opening or your name needs renewing. It isn't
            shown on your website.
          </small>
        </label>
      </section>

      {saveError && <ErrorBox error={saveError} />}
      <div className="actions">
        <button className="btn btn-primary" type="submit" disabled={saving}>
          {saving ? "Saving…" : "Save"}
        </button>
    </>
  );
}

export function ErrorBox({ error }: { error: ApiError }) {
  return (
    <div className="status status-error" role="alert">
      <p>{error.message}</p>
      {error.details !== null && typeof error.details !== "string" && (
        <details>
          <summary>Details</summary>
          <pre>{JSON.stringify(error.details, null, 2)}</pre>
        </details>
      )}
    </div>
  );
}

