// S9F Phase 2 checkpoint screenshots. usage: node shoot.js <base_url> <out_dir>
const { chromium } = require("playwright");
const fs = require("fs");
const path = require("path");
const os = require("os");

const [base, out] = process.argv.slice(2);
fs.mkdirSync(out, { recursive: true });
const exe = path.join(os.homedir(), "AppData/Local/ms-playwright/chromium-1243/chrome-win64/chrome.exe");
const wait = (ms) => new Promise((r) => setTimeout(r, ms));

async function shot(page, name) {
  for (const [label, width] of [["phone", 375], ["laptop", 1440]]) {
    await page.setViewportSize({ width, height: label === "phone" ? 812 : 900 });
    await wait(450);
    const overflow = await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth);
    if (overflow > 0) console.log(`WARNING ${name} ${label}: sideways overflow ${overflow}px`);
    await page.screenshot({ path: path.join(out, `${name}-${label}.png`), fullPage: true });
  }
  await page.setViewportSize({ width: 375, height: 812 });
  console.log("shot", name);
}

async function signIn(page, email, prefix) {
  await page.goto(base + "/#/signin");
  await page.waitForSelector("input[type=email]");
  if (prefix) await shot(page, `${prefix}-1-sign-in`);
  await page.fill("input[type=email]", email);
  await page.click("button[type=submit]");
  await page.waitForSelector("text=Check your email");
  if (prefix) await shot(page, `${prefix}-2-check-email`);
  await page.click("text=Open the sign-in link");
  await page.waitForSelector("button:has-text('Sign in')");
  if (prefix) await shot(page, `${prefix}-3-confirm`);
  await page.click("main button:has-text('Sign in')");
  await page.waitForSelector("h1:has-text('Your shops')");
}

(async () => {
  const browser = await chromium.launch({ executablePath: exe });
  const ctx = () => browser.newContext({ viewport: { width: 375, height: 812 }, deviceScaleFactor: 1 });

  // A signs up and makes a shop
  const a = await (await ctx()).newPage();
  await signIn(a, "a@example.org", "01-a");
  await shot(a, "01-a-4-pending-no-shops");
  await a.goto(base + "/#/try");
  await a.waitForSelector(".chip");
  await a.click(".chip >> nth=0");
  await a.click("button[type=submit]");
  await a.waitForSelector("h1:has-text('Check your details')", { timeout: 20000 });
  const shopUrl = a.url();
  const shopId = shopUrl.match(/#\/b\/(\d+)/)[1];
  await shot(a, "01-a-5-shop-under-account");
  await a.goto(base + "/#/shops");
  await a.waitForSelector(".shops li");
  await shot(a, "01-a-6-my-shops-pending");

  // The team approves A
  const team = await (await ctx()).newPage();
  await signIn(team, "team@example.org");
  await team.goto(base + "/#/admin");
  await team.waitForSelector("text=Waiting for approval");
  await shot(team, "02-team-1-queue");
  await team.click("li:has-text('a@example.org') >> button:has-text('Approve')");
  await team.waitForSelector("text=Nobody is waiting");
  await shot(team, "02-team-2-approved");

  // A sees the approved state and the real-launch button
  await a.goto(base + "/#/account");
  await a.waitForSelector("text=Approved");
  await shot(a, "03-a-1-account-approved");
  await a.goto(base + `/#/b/${shopId}/launch`);
  await a.waitForSelector("text=Launch for real");
  await shot(a, "03-a-2-launch-for-real");

  // B can't see A's shop
  const b = await (await ctx()).newPage();
  await signIn(b, "b@example.org");
  await shot(b, "04-b-1-my-shops-empty");
  await b.goto(base + `/#/b/${shopId}`);
  await b.waitForSelector("text=We couldn't find that shop.");
  await shot(b, "04-b-2-cannot-open-a-shop");

  // A guest trying it without signing in
  const g = await (await ctx()).newPage();
  await g.goto(base + "/#/try");
  await g.waitForSelector(".chip");
  await g.click(".chip >> nth=1");
  await g.click("button[type=submit]");
  await g.waitForSelector("h1:has-text('Check your details')", { timeout: 20000 });
  await shot(g, "05-guest-practice-banner");

  await browser.close();
  console.log("done", shopId);
})().catch((e) => {
  console.error(e);
  process.exit(1);
});

