"""Fetch a URL over HTTPS and report status + certificate validity (for launch checks)."""

import socket
import ssl
from dataclasses import dataclass
from datetime import UTC, datetime, timedelta
from typing import Protocol
from urllib.parse import urlsplit

import httpx

from app.config import Settings


@dataclass(frozen=True)
class ProbeResult:
    ok: bool  # HTTP 2xx/3xx over HTTPS with a valid certificate
    status: int | None
    cert_valid: bool
    body_snippet: str = ""
    error: str = ""


class HttpProbe(Protocol):
    def fetch(self, url: str) -> ProbeResult: ...
    def cert_expires(self, host: str) -> datetime | None:
        """End date of the HTTPS certificate served for `host` (None if it can't be read)."""
        ...


class RealHttpProbe:
    def __init__(self, timeout: float = 10.0, transport: httpx.BaseTransport | None = None):
        self._http = httpx.Client(timeout=timeout, follow_redirects=True, transport=transport)

    def fetch(self, url: str) -> ProbeResult:
        try:
            r = self._http.get(url)
        except httpx.ConnectError as e:
            cert_bad = isinstance(e.__cause__, ssl.SSLError) or "CERTIFICATE" in str(e).upper()
            return ProbeResult(False, None, not cert_bad, error=type(e).__name__)
        except httpx.HTTPError as e:
            return ProbeResult(False, None, False, error=type(e).__name__)
        https = urlsplit(str(r.url)).scheme == "https"
        return ProbeResult(https and r.status_code < 400, r.status_code, https, r.text[:2000])

    def cert_expires(self, host: str) -> datetime | None:
        """TODO(real): verify against a real Caddy-served host."""
        try:
            ctx = ssl.create_default_context()
            with socket.create_connection((host, 443), timeout=10) as raw, ctx.wrap_socket(raw, server_hostname=host) as tls:
                not_after = tls.getpeercert().get("notAfter")
        except (OSError, ssl.SSLError):
            return None
        return datetime.fromtimestamp(ssl.cert_time_to_seconds(not_after), UTC) if not_after else None


class FakeHttpProbe:
    """Practice mode: a site 'is up with a valid certificate' when its host is in the
    fake DNS and not listed in `broken_cert` / `down`."""

    def __init__(self, settings: Settings | None = None):
        self.down: set[str] = set()
        self.broken_cert: set[str] = set()
        self.calls: list[str] = []
        self.cert_end: dict[str, datetime] = {}  # host -> certificate end (default: 80 days from now)

    def cert_expires(self, host: str) -> datetime | None:
        if host in self.down or host in self.broken_cert:
            return None
        return self.cert_end.get(host) or datetime.now(UTC) + timedelta(days=80)

    def fetch(self, url: str) -> ProbeResult:
        self.calls.append(url)
        host = urlsplit(url).hostname or ""
        if host in self.down:
            return ProbeResult(False, None, True, error="ConnectTimeout")
        if host in self.broken_cert:
            return ProbeResult(False, None, False, error="certificate verify failed")
        return ProbeResult(True, 200, True, "<html>ok</html>")
"""Public DNS lookups (dnspython) for launch checks."""

from typing import Protocol

import dns.exception
import dns.resolver


class DnsResolver(Protocol):
    def resolve(self, name: str, rtype: str) -> list[str]: ...


class RealDnsResolver:
    def __init__(self, nameservers: list[str] | None = None, timeout: float = 5.0):
        self._r = dns.resolver.Resolver()
        if nameservers:
            self._r.nameservers = nameservers
        self._r.lifetime = timeout

    def resolve(self, name: str, rtype: str) -> list[str]:
        try:
            answer = self._r.resolve(name, rtype)
        except (dns.resolver.NXDOMAIN, dns.resolver.NoAnswer, dns.exception.Timeout):
            return []
        return [r.to_text() for r in answer]


class FakeDnsResolver:
    def __init__(self, records: dict[tuple[str, str], list[str]] | None = None):
        self.records = dict(records or {})

    def set(self, name: str, rtype: str, values: list[str]) -> None:
        self.records[(name.lower().rstrip("."), rtype.upper())] = values

    def resolve(self, name: str, rtype: str) -> list[str]:
        return list(self.records.get((name.lower().rstrip("."), rtype.upper()), []))


def record_text(rec: dict) -> str:
    """GoDaddy record dict -> the text a DNS lookup would return."""
    if rec["type"] == "MX":
        return f"{rec.get('priority', 10)} {rec['data']}."
    if rec["type"] == "TXT":
        return f'"{rec["data"]}"'
    if rec["type"] in ("CNAME", "NS"):
        return rec["data"].rstrip(".") + "."
    return rec["data"]


class ZoneBackedResolver:
    """Fake *authoritative* DNS that answers from a FakeGoDaddyClient's zones,
    so practice-mode launches can be 'proven' end to end. `hide` lets tests and
    the demo fault simulate a record that hasn't spread yet / went missing."""

    def __init__(self, godaddy):
        self.godaddy = godaddy
        self.hide: set[tuple[str, str]] = set()

    def resolve(self, name: str, rtype: str) -> list[str]:
        fqdn, rtype = name.lower().rstrip("."), rtype.upper()
        if (fqdn, rtype) in self.hide:
            return []
        for zone, records in self.godaddy.zones.items():
            if fqdn == zone:
                label = "@"
            elif fqdn.endswith("." + zone):
                label = fqdn[: -len(zone) - 1]
            else:
                continue
            return [record_text(r) for r in records if r["type"] == rtype and r["name"] == label]
        return []
"""All outside services the launch engine uses, bundled so they can be swapped.

USE_FAKES=true (default): one shared in-memory "fake world" per process
(GoDaddy zones, availability, mailbox, authoritative DNS answering from the
fake zones, HTTP probe). Nothing real changes. USE_FAKES=false: real clients;
the parts not built yet raise NotImplementedError (see PROGRESS.md).
"""

import time
from collections.abc import Callable
from dataclasses import dataclass, field
from functools import lru_cache

from app.checks.dns_resolver import DnsResolver, ZoneBackedResolver
from app.checks.http_probe import FakeHttpProbe, HttpProbe, RealHttpProbe
from app.config import Settings, get_settings
from app.godaddy.availability import AvailabilityChecker, FakeAvailabilityChecker, GoDaddyAvailabilityChecker
from app.godaddy.client import FakeGoDaddyClient, GoDaddy, GoDaddyClient
from app.godaddy.email import FakeMailboxProvider, MailboxProvider, TitanMailboxProvider
from app.mail.imap import FakeInboxReader, ImapInboxReader, InboxReader
from app.mail.providers import planned_dkim_name, provider_for
from app.mail.smtp import FakeMailer, Mailer, SmtpMailer


class DeliveringFakeMailer(FakeMailer):
    """Practice mode: 'sent' mail lands in the fake inbox, like a working mailbox would."""

    def __init__(self, inbox: FakeInboxReader, sender: str):
        super().__init__()
        self.inbox, self.sender, self.drop = inbox, sender, False

    def send(self, *, to: str, subject: str, body: str, html: str | None = None) -> str:
        message_id = super().send(to=to, subject=subject, body=body, html=html)
        if not self.drop:
            self.inbox.deliver(sender=self.sender, to=to, subject=subject, body=body)
        return message_id


@dataclass
class Integrations:
    godaddy: GoDaddy
    availability: AvailabilityChecker
    mailbox: MailboxProvider
    dns: DnsResolver  # must ask GoDaddy's AUTHORITATIVE nameservers, not a cache
    http: HttpProbe
    mailer: Mailer  # used by the launch check's test order
    inbox: InboxReader  # demo mailbox, to prove the test order arrived
    sleep: Callable[[float], None] = field(default=time.sleep)
    fake: bool = False


def fake_integrations(settings: Settings, sleep: Callable[[float], None] | None = None) -> Integrations:
    gd = FakeGoDaddyClient(owned={settings.app_domain}, app_domain=settings.app_domain)
    provider = provider_for(settings)
    # The pretend world starts like the real one: the domain the app's mailbox is on already has
    # working mail settings (GoDaddy set them when the mailbox was bought). Checks only read them.
    mail_zone = settings.smtp_user.rsplit("@", 1)[-1].lower()
    gd.zones.setdefault(mail_zone, []).extend(
        [{"type": "MX", "name": "@", "data": host, "priority": prio, "ttl": 3600} for prio, host in provider.mx]
        + [{"type": "TXT", "name": "@", "data": provider.spf, "ttl": 3600},
           {"type": "TXT", "name": planned_dkim_name(provider), "data": "v=DKIM1; k=rsa; p=PRETENDKEY", "ttl": 3600},
           {"type": "TXT", "name": "_dmarc", "data": "v=DMARC1; p=quarantine", "ttl": 3600}])
    inbox = FakeInboxReader()
    return Integrations(
        godaddy=gd,
        availability=FakeAvailabilityChecker(),
        mailbox=FakeMailboxProvider(existing={settings.smtp_user}, dkim_name=planned_dkim_name(provider)),
        dns=ZoneBackedResolver(gd),
        http=FakeHttpProbe(settings),
        mailer=DeliveringFakeMailer(inbox, settings.smtp_user),
        inbox=inbox,
        sleep=sleep or (lambda _s: None),
        fake=True,
    )


def real_integrations(settings: Settings) -> Integrations:
    from app.checks.dns_resolver import RealDnsResolver

    return Integrations(
        godaddy=GoDaddyClient(settings),
        availability=GoDaddyAvailabilityChecker(),
        mailbox=TitanMailboxProvider(),
        # TODO(real): pass GoDaddy's authoritative nameserver IPs (ns*.domaincontrol.com) for the zone.
        dns=RealDnsResolver(),
        http=RealHttpProbe(),
        mailer=SmtpMailer(settings),
        inbox=ImapInboxReader(settings),
    )


@lru_cache
def _shared_fakes() -> Integrations:
    return fake_integrations(get_settings())


def get_integrations() -> Integrations:
    """FastAPI dependency: the server's own integrations (real when USE_FAKES=false). Tests override this."""
    settings = get_settings()
    return _shared_fakes() if settings.use_fakes else real_integrations(settings)


def get_practice_integrations() -> Integrations:
    """FastAPI dependency: the shared fake world, used for practice businesses. Tests override this."""
    return _shared_fakes()


def for_business(business, server: Integrations, practice: Integrations) -> Integrations:
    """Practice businesses NEVER get real integrations, whatever the server mode."""
    return practice if business.practice or server.fake else server

