            }
          >
            {active ? "Make a new link (the old one stops)" : "Make a share link"}
          </button>
          {active && (
            <button
              className="btn btn-ghost btn-sm"
              onClick={() =>
                run(async () => {
                  await api.unshare(businessId);
                  setActive(false);
                  setUrl(null);
                })
              }
            >
              Turn the link off
            </button>
          )}
        </div>
        {error && <ErrorBox error={error} />}
      </section>
    </>
  );
}

