const { chromium } = require("playwright");
const path = require("path");
const os = require("os");
const [base, out] = process.argv.slice(2);
const exe = path.join(os.homedir(), "AppData/Local/ms-playwright/chromium-1243/chrome-win64/chrome.exe");
(async () => {
  const browser = await chromium.launch({ executablePath: exe });
  const page = await (await browser.newContext({ viewport: { width: 375, height: 812 }, reducedMotion: "reduce" })).newPage();
  await page.goto(base + "/#/try");
  await page.waitForSelector(".chip");
  await page.click(".chip >> nth=0");
  await page.click("button[type=submit]");
  await page.waitForSelector("h1:has-text('Check your details')", { timeout: 20000 });
  const id = page.url().match(/#\/b\/(\d+)/)[1];
  await page.goto(base + `/#/b/${id}/launch`);
  await page.click("text=Practise with the free address");
  await page.waitForSelector("button:has-text('Approve')", { timeout: 20000 });
  await page.click("button:has-text('Approve')");
  await page.goto(base + `/#/b/${id}/report`);
  await page.waitForSelector(".proof-count", { timeout: 30000 });
  await page.waitForTimeout(800);
  for (const [label, width] of [["phone", 375], ["laptop", 1440]]) {
    await page.setViewportSize({ width, height: 900 });
    await page.waitForTimeout(400);
    const overflow = await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth);
    if (overflow > 0) console.log(`WARNING ${label}: overflow ${overflow}`);
    await page.screenshot({ path: path.join(out, `06-proof-report-${label}.png`), fullPage: true });
  }
  await page.goto(base + "/#/");
  await page.waitForSelector("#check");
  await page.locator("#check").scrollIntoViewIfNeeded();
  await page.waitForTimeout(800);
  await page.locator("#check").screenshot({ path: path.join(out, "07-check-any-address-laptop.png") });
  await browser.close();
  console.log("done", id);
})().catch((e) => {
  console.error(e);
  process.exit(1);
});

